//! Comments and markup, stored as standard PDF annotations.
//!
//! Only annotation types from the PDF specification are written (`Text` sticky notes,
//! `Highlight`, `Underline`, `StrikeOut`), each with the usual entries (`Contents`, `T` author,
//! `M` date, `C` colour, `QuadPoints`/`Rect`) and an appearance stream generated by MuPDF.
//! Other PDF readers show, edit and reply to them like their own, and comments made in other
//! readers show up here. Nothing is kept outside the PDF.

use mupdf::color::AnnotationColor;
use mupdf::pdf::{PdfAnnotation, PdfAnnotationType, PdfObject, PdfPage};
use mupdf::{Point, Quad, Rect, TextPageFlags};

use crate::engine::{Engine, HitQuad, Result, err};

/// The kinds of annotation the reader can create.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum MarkupKind {
    Highlight,
    Underline,
    StrikeOut,
}

/// What an existing annotation is, for display.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AnnotKind {
    Note,
    Highlight,
    Underline,
    StrikeOut,
    Squiggly,
    FreeText,
    Ink,
    Shape,
    Stamp,
    Caret,
    FileAttachment,
    Other,
}

impl AnnotKind {
    pub fn label(self) -> &'static str {
        match self {
            AnnotKind::Note => "Note",
            AnnotKind::Highlight => "Highlight",
            AnnotKind::Underline => "Underline",
            AnnotKind::StrikeOut => "Strike-out",
            AnnotKind::Squiggly => "Squiggly underline",
            AnnotKind::FreeText => "Text box",
            AnnotKind::Ink => "Drawing",
            AnnotKind::Shape => "Shape",
            AnnotKind::Stamp => "Stamp",
            AnnotKind::Caret => "Insertion mark",
            AnnotKind::FileAttachment => "Attachment",
            AnnotKind::Other => "Annotation",
        }
    }
}

#[derive(Clone, Debug)]
pub struct AnnotInfo {
    pub page: usize,
    /// PDF object number: identifies the annotation until the file is saved or reloaded.
    pub xref: i32,
    pub kind: AnnotKind,
    /// Bounding box in page points: (x0, y0, x1, y1), top-left origin.
    pub rect: (f32, f32, f32, f32),
    /// Marked text areas (highlight, underline, strike-out); empty for other kinds.
    pub quads: Vec<HitQuad>,
    pub author: String,
    pub contents: String,
    /// The annotation's own colour (RGB), if it has one.
    pub color: Option<[u8; 3]>,
}

/// Text selected between two points on a page.
#[derive(Clone, Debug, Default)]
pub struct TextSelection {
    pub quads: Vec<HitQuad>,
    pub text: String,
}

fn rgb(c: [u8; 3]) -> AnnotationColor {
    AnnotationColor::Rgb { red: c[0] as f32 / 255.0, green: c[1] as f32 / 255.0, blue: c[2] as f32 / 255.0 }
}

/// Colours for people's comments: distinct from one another, light enough to read text
/// through as a highlight and strong enough to see as an underline or a note.
pub const COMMENT_PALETTE: [[u8; 3]; 8] = [
    [0xff, 0xd4, 0x00], // yellow
    [0x5b, 0xd7, 0x5b], // green
    [0x4d, 0xa3, 0xff], // blue
    [0xff, 0x6f, 0xae], // pink
    [0xff, 0x9a, 0x3c], // orange
    [0xb5, 0x8c, 0xff], // purple
    [0x2e, 0xc4, 0xb6], // teal
    [0xff, 0x5c, 0x5c], // red
];

/// The colour for a person's new comments in a document, given the comments already there.
///
/// Someone who has commented before keeps the colour they used. A new person gets a colour
/// of the palette that nobody else in the document is using (their "own" palette colour if
/// it is free, otherwise the next free one), so different people can be told apart. Comments
/// made in other software count too, whatever colour that software gave them.
pub fn author_color(author: &str, existing: &[AnnotInfo]) -> [u8; 3] {
    let same = |a: &str| a.trim().eq_ignore_ascii_case(author.trim());
    // Keep the colour this person used most recently.
    if let Some(color) = existing.iter().rev().filter(|a| same(&a.author)).find_map(|a| a.color) {
        return color;
    }
    let taken: Vec<[u8; 3]> = existing.iter().filter(|a| !same(&a.author)).filter_map(|a| a.color).collect();
    let close = |a: [u8; 3], b: [u8; 3]| (0..3).map(|i| (a[i] as i32 - b[i] as i32).pow(2)).sum::<i32>() < 50 * 50;
    // A stable starting point per name (FNV-1a), so the same person tends to get the same colour everywhere.
    let start = author.trim().to_lowercase().bytes().fold(0xcbf2_9ce4_8422_2325u64, |h, b| (h ^ b as u64).wrapping_mul(0x0000_0100_0000_01b3)) as usize;
    (0..COMMENT_PALETTE.len())
        .map(|i| COMMENT_PALETTE[(start + i) % COMMENT_PALETTE.len()])
        .find(|c| !taken.iter().any(|t| close(*c, *t)))
        .unwrap_or(COMMENT_PALETTE[start % COMMENT_PALETTE.len()])
}

fn kind_of(t: PdfAnnotationType) -> Option<AnnotKind> {
    use PdfAnnotationType as T;
    Some(match t {
        // Not comments: links, form fields and the popup windows that belong to other annotations.
        T::Link | T::Popup | T::Widget => return None,
        T::Text => AnnotKind::Note,
        T::Highlight => AnnotKind::Highlight,
        T::Underline => AnnotKind::Underline,
        T::StrikeOut => AnnotKind::StrikeOut,
        T::Squiggly => AnnotKind::Squiggly,
        T::FreeText => AnnotKind::FreeText,
        T::Ink => AnnotKind::Ink,
        T::Line | T::Square | T::Circle | T::Polygon | T::PolyLine => AnnotKind::Shape,
        T::Stamp => AnnotKind::Stamp,
        T::Caret => AnnotKind::Caret,
        T::FileAttachment => AnnotKind::FileAttachment,
        _ => AnnotKind::Other,
    })
}

fn hit_quad(q: &Quad) -> HitQuad {
    [(q.ul.x, q.ul.y), (q.ur.x, q.ur.y), (q.ll.x, q.ll.y), (q.lr.x, q.lr.y)]
}

fn to_quad(q: &HitQuad) -> Quad {
    let p = |(x, y): (f32, f32)| Point::new(x, y);
    Quad::new(p(q[0]), p(q[1]), p(q[2]), p(q[3]))
}

fn describe(page: usize, annot: &PdfAnnotation) -> Option<AnnotInfo> {
    let kind = kind_of(annot.r#type().ok()?)?;
    let r = annot.rect().or_else(|_| annot.bounds()).ok()?;
    let quads = match kind {
        AnnotKind::Highlight | AnnotKind::Underline | AnnotKind::StrikeOut | AnnotKind::Squiggly => {
            annot.quad_points().unwrap_or_default().iter().map(hit_quad).collect()
        }
        _ => Vec::new(),
    };
    Some(AnnotInfo {
        page,
        xref: annot.xref().ok()?,
        kind,
        rect: (r.x0, r.y0, r.x1, r.y1),
        quads,
        author: annot.author().ok().flatten().unwrap_or_default().to_owned(),
        contents: annot.contents().ok().flatten().unwrap_or_default().to_owned(),
        color: annot.color().ok().flatten().map(|c| {
            let byte = |v: f32| (v.clamp(0.0, 1.0) * 255.0).round() as u8;
            match c {
                AnnotationColor::Gray(g) => [byte(g); 3],
                AnnotationColor::Rgb { red, green, blue } => [byte(red), byte(green), byte(blue)],
                AnnotationColor::Cmyk { cyan, magenta, yellow, key } => {
                    [byte((1.0 - cyan) * (1.0 - key)), byte((1.0 - magenta) * (1.0 - key)), byte((1.0 - yellow) * (1.0 - key))]
                }
            }
        }),
    })
}

/// The current time as a PDF date string in UTC, e.g. `D:20261114093000Z`.
fn pdf_date_now() -> String {
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |d| d.as_secs());
    pdf_date(secs)
}

fn pdf_date(unix_secs: u64) -> String {
    let (days, rem) = ((unix_secs / 86_400) as i64, unix_secs % 86_400);
    // Days since 1970-01-01 to a calendar date (Howard Hinnant's algorithm).
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = yoe + era * 400 + i64::from(month <= 2);
    format!(
        "D:{year:04}{month:02}{day:02}{:02}{:02}{:02}Z",
        rem / 3600,
        rem % 3600 / 60,
        rem % 60
    )
}

/// The entries other readers use to sort, thread and identify comments.
struct Stamp {
    date: PdfObject,
    /// Set for new annotations only: creation date and a unique name (`NM`).
    created: Option<(PdfObject, PdfObject)>,
}

impl Stamp {
    fn apply(self, annot: &PdfAnnotation) -> std::result::Result<(), mupdf::Error> {
        let mut obj = annot.object();
        obj.dict_put("M", self.date)?;
        if let Some((created, name)) = self.created {
            obj.dict_put("CreationDate", created)?;
            obj.dict_put("NM", name)?;
        }
        Ok(())
    }
}

impl Engine {
    fn stamp(&mut self, new: bool) -> Result<Stamp> {
        let now = pdf_date_now();
        let doc = self.pdf_mut()?;
        let date = doc.new_string(&now).map_err(err)?;
        let created = if new {
            let nanos = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map_or(0, |d| d.as_nanos());
            let name = format!("rr-{nanos:x}-{:x}", doc.count_objects().unwrap_or(0));
            Some((doc.new_string(&now).map_err(err)?, doc.new_string(&name).map_err(err)?))
        } else {
            None
        };
        Ok(Stamp { date, created })
    }

    fn pdf_page(&mut self, page: usize) -> Result<PdfPage> {
        if page >= self.page_count() {
            return Err(format!("Page {} does not exist", page + 1));
        }
        self.pdf_mut()?.load_pdf_page(page as i32).map_err(err)
    }

    fn find_annotation(page: &PdfPage, xref: i32) -> Result<PdfAnnotation> {
        page.annotations()
            .find(|a| a.xref().is_ok_and(|x| x == xref))
            .ok_or_else(|| "That comment no longer exists".to_owned())
    }

    /// Comments on one page, in the order they are stored. Empty for non-PDF documents.
    pub fn page_annotations(&self, page: usize) -> Vec<AnnotInfo> {
        let Some(doc) = self.pdf() else { return Vec::new() };
        let Ok(p) = doc.load_pdf_page(page as i32) else {
            return Vec::new();
        };
        p.annotations().filter_map(|a| describe(page, &a)).collect()
    }

    /// Every comment in the document, by page.
    pub fn all_annotations(&self) -> Vec<AnnotInfo> {
        (0..self.page_count())
            .flat_map(|page| self.page_annotations(page))
            .collect()
    }

    /// The text between two points on a page (as if dragging the mouse from `a` to `b`),
    /// with the boxes to draw for it. Works on every document type.
    pub fn select_text(&self, page: usize, a: (f32, f32), b: (f32, f32)) -> Result<TextSelection> {
        let p = self.base().load_page(page as i32).map_err(err)?;
        let mut tp = p.to_text_page(TextPageFlags::empty()).map_err(err)?;
        let buffer = vec![Quad::new(Point::new(0.0, 0.0), Point::new(0.0, 0.0), Point::new(0.0, 0.0), Point::new(0.0, 0.0)); 1024];
        let count = tp
            .highlight_selection(Point::new(a.0, a.1), Point::new(b.0, b.1), &buffer)
            .map_err(err)?
            .clamp(0, buffer.len() as i32) as usize;
        let quads: Vec<HitQuad> = buffer[..count].iter().map(hit_quad).collect();

        // Collect the characters whose centre lies inside a selected box, line by line.
        let boxes: Vec<(f32, f32, f32, f32)> = quads
            .iter()
            .map(|q| {
                let xs = q.iter().map(|p| p.0);
                let ys = q.iter().map(|p| p.1);
                (
                    xs.clone().fold(f32::MAX, f32::min),
                    ys.clone().fold(f32::MAX, f32::min),
                    xs.fold(f32::MIN, f32::max),
                    ys.fold(f32::MIN, f32::max),
                )
            })
            .collect();
        let inside = |q: &Quad| {
            let (cx, cy) = ((q.ul.x + q.lr.x) * 0.5, (q.ul.y + q.lr.y) * 0.5);
            boxes
                .iter()
                .any(|&(x0, y0, x1, y1)| cx >= x0 && cx <= x1 && cy >= y0 && cy <= y1)
        };
        let mut text = String::new();
        for block in tp.blocks() {
            for line in block.lines() {
                let before = text.len();
                for ch in line.chars() {
                    if inside(&ch.quad()) {
                        if let Some(c) = ch.char() {
                            text.push(c);
                        }
                    }
                }
                if text.len() > before {
                    text.push('\n');
                }
            }
        }
        Ok(TextSelection { quads, text: text.trim_end().to_owned() })
    }

    /// Highlight, underline or strike out text. `quads` come from [`Engine::select_text`].
    /// Returns the new annotation's object number.
    pub fn add_markup(
        &mut self,
        page: usize,
        kind: MarkupKind,
        quads: &[HitQuad],
        author: &str,
        contents: &str,
        color: [u8; 3],
    ) -> Result<i32> {
        if quads.is_empty() {
            return Err("Select some text first".into());
        }
        let stamp = self.stamp(true)?;
        let mut p = self.pdf_page(page)?;
        let subtype = match kind {
            MarkupKind::Highlight => PdfAnnotationType::Highlight,
            MarkupKind::Underline => PdfAnnotationType::Underline,
            MarkupKind::StrikeOut => PdfAnnotationType::StrikeOut,
        };
        let mut annot = p.create_annotation(subtype).map_err(err)?;
        let result = (|| {
            annot.set_quad_points(quads.iter().map(to_quad).collect::<Vec<_>>())?;
            annot.set_color(rgb(color))?;
            annot.set_author(author)?;
            if !contents.is_empty() {
                annot.set_contents(contents)?;
            }
            stamp.apply(&annot)?;
            annot.update()?;
            annot.xref()
        })();
        self.finish_annotation_edit(p, annot, result)
    }

    /// Add a sticky note at a point on the page.
    pub fn add_note(&mut self, page: usize, at: (f32, f32), contents: &str, author: &str, color: [u8; 3]) -> Result<i32> {
        let stamp = self.stamp(true)?;
        let mut p = self.pdf_page(page)?;
        let rect = Rect::new(at.0, at.1, at.0 + 20.0, at.1 + 20.0);
        let mut annot = p.create_annotation(PdfAnnotationType::Text).map_err(err)?;
        let result = (|| {
            annot.set_rect(rect)?;
            annot.set_icon_name("Comment")?;
            annot.set_color(rgb(color))?;
            annot.set_author(author)?;
            annot.set_contents(contents)?;
            stamp.apply(&annot)?;
            annot.update()?;
            annot.xref()
        })();
        self.finish_annotation_edit(p, annot, result)
    }

    /// If building a new annotation failed half-way, remove it again so no broken
    /// annotation is left in the file.
    fn finish_annotation_edit(
        &mut self,
        mut page: PdfPage,
        annot: PdfAnnotation,
        result: std::result::Result<i32, mupdf::Error>,
    ) -> Result<i32> {
        match result {
            Ok(xref) => {
                drop(annot);
                let _ = page.update();
                self.mark_dirty();
                Ok(xref)
            }
            Err(e) => {
                let _ = page.delete_annotation(annot);
                Err(err(e))
            }
        }
    }

    /// Highlight every occurrence of `text` on a page (optionally with a comment on the
    /// first one). Returns how many were highlighted.
    pub fn highlight_text(&mut self, page: usize, text: &str, author: &str, comment: &str, color: [u8; 3]) -> Result<usize> {
        let hits = self.search_page(page, text)?;
        if hits.is_empty() {
            return Err(format!("\"{text}\" was not found on page {}", page + 1));
        }
        // One annotation per occurrence would clutter the comment list; one covers them all.
        self.add_markup(page, MarkupKind::Highlight, &hits, author, comment, color)?;
        Ok(hits.len())
    }

    /// Change the comment text of an annotation (ours or another reader's).
    pub fn set_annotation_contents(&mut self, page: usize, xref: i32, contents: &str) -> Result<()> {
        let stamp = self.stamp(false)?;
        let mut p = self.pdf_page(page)?;
        let mut annot = Self::find_annotation(&p, xref)?;
        annot.set_contents(contents).map_err(err)?;
        stamp.apply(&annot).map_err(err)?;
        annot.update().map_err(err)?;
        drop(annot);
        let _ = p.update();
        self.mark_dirty();
        Ok(())
    }

    pub fn delete_annotation(&mut self, page: usize, xref: i32) -> Result<()> {
        let mut p = self.pdf_page(page)?;
        let annot = Self::find_annotation(&p, xref)?;
        p.delete_annotation(annot).map_err(err)?;
        let _ = p.update();
        self.mark_dirty();
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::pdf_date;

    #[test]
    fn pdf_dates() {
        assert_eq!(pdf_date(0), "D:19700101000000Z");
        assert_eq!(pdf_date(951_782_400), "D:20000229000000Z"); // leap day
        assert_eq!(pdf_date(1_794_648_645), "D:20261114093045Z");
    }
}
